// One import point for the Go service (generated by `wails3 generate bindings`; rerun it after changing desktop/*.go).
export {Notes} from '../bindings/github.com/dasariprashant0/gloamlog/desktop';
export type {Hit, Overview, Page, Week} from '../bindings/github.com/dasariprashant0/gloamlog/desktop';
export {DayStatus} from '../bindings/github.com/dasariprashant0/gloamlog/internal/core';
export type {BackupInfo, CarryCard, MonthCell, Settings} from '../bindings/github.com/dasariprashant0/gloamlog/internal/core';

/** "2026-10-14" -> a local Date at midnight. */
export function dayDate(day: string): Date {
    const [y, m, d] = day.split('-').map(Number);
    return new Date(y, m - 1, d);
}

/** "Wed 14 Oct", the short form used in lists and notices. */
export function shortDay(day: string): string {
    return dayDate(day).toLocaleDateString('en-GB', {weekday: 'short', day: 'numeric', month: 'short'});
}

/** "Yesterday", "3 days ago", "2 weeks ago"... for days before today ("" for today and later). */
export function relativeDay(day: string, today: string): string {
    const days = Math.round((dayDate(today).getTime() - dayDate(day).getTime()) / 86_400_000);
    if (days <= 0) return '';
    if (days === 1) return 'Yesterday';
    if (days < 14) return `${days} days ago`;
    if (days < 60) return `${Math.round(days / 7)} weeks ago`;
    if (days < 365) return `${Math.round(days / 30)} months ago`;
    const years = Math.round(days / 365);
    return years === 1 ? 'A year ago' : `${years} years ago`;
}

/** Day key `n` days from `day` (calendar days, so DST never shifts it). */
export function addDays(day: string, n: number): string {
    const d = dayDate(day);
    d.setDate(d.getDate() + n);
    return [d.getFullYear(), String(d.getMonth() + 1).padStart(2, '0'), String(d.getDate()).padStart(2, '0')].join('-');
}

export const plural = (n: number, word: string) => `${n} ${word}${n === 1 ? '' : 's'}`;
